questionvariables.text:
/* Randomised measurements; unique maxima are deliberate. */
hshift:rand(5)-2;
gshift:rand(5)-2;
dshift:rand(5)-2;
heights:makelist(8+2*k+hshift,k,1,12);
growth0:[5,7,8,6,10,9,8,9,12,11,14,13];
growth:makelist(growth0[k]+gshift,k,1,12);
diam0:[12,17,13,21,15,19,18,14,25,16,22,20];
diameters:makelist(diam0[k]+dshift,k,1,12);
treat:makelist(if k<=6 then 0 else 1,k,1,12);
plots:makelist(ceiling(k/2),k,1,12);
tree_data:makelist([sconcat("T",k),sconcat("P",plots[k]),if treat[k]=1 then "Fertilised" else "Control",heights[k],growth[k],diameters[k]],k,1,12);
tree_data:random_permutation(tree_data);
lab:["Tree_ID","Plot_ID","Treatment","Height_m","Growth_cm","Diameter_cm"];
ta_fastest_tree:11;
ta_height_fastest:heights[11];
ta_growth_fastest:growth[11];
ta_tallest_tree:12;
ta_tallest_height:heights[12];
ta_thickest_tree:9;
ta_thickest_diameter:diameters[9];
ta_control_max:growth[5];
ta_control_max_tree:5;
ta_control_max_height:heights[5];
ta_control_mean:sum(growth[k],k,1,6)/6;
ta_fert_max:growth[11];
ta_fert_max_tree:11;
ta_fert_max_height:heights[11];
ta_fert_mean:sum(growth[k],k,7,12)/6;
ta_tallest_diameter:diameters[12];
ta_tallest_growth:growth[12];
ta_thickest_height:heights[9];
ta_thickest_growth:growth[9];
/* Mapping codes: x=1 height; y=2 growth; colour=1 treatment;
   size=1 diameter; panels=1 treatment. */
ta_mapx:2;
ta_mapy:1;
ta_mapc:1;
ta_maps:1;
ta_mapp:1;
